import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (T-- > 0) { int N = Integer.parseInt(br.readLine()); long[] counts = new long[32]; for (int i = 0; i < N; i++) { String s = br.readLine(); int mask = 0; for (int j = 0; j < s.length(); j++) { char c = s.charAt(j); if (c == 'a') mask |= 1; else if (c == 'e') mask |= 2; else if (c == 'i') mask |= 4; else if (c == 'o') mask |= 8; else if (c == 'u') mask |= 16; } counts[mask]++; } long ans = 0; for (int i = 0; i < 32; i++) { if (counts[i] == 0) continue; for (int j = i; j < 32; j++) { if (counts[j] == 0) continue; if ((i | j) == 31) { if (i == j) { ans += counts[i] * (counts[i] - 1) / 2; } else { ans += counts[i] * counts[j]; } } } } out.println(ans); } out.flush(); out.close(); } }